import React from "react";
import {
  FaSearch,
  FaFilter,
  FaTh,
  FaBars,
} from "react-icons/fa";
import FilterModal from "./FilterModalComponent";
import RequestRecords from "./RequestRecordsComponent";
import AuthCheck from "./AuthCheckComponent";
import Loader from "./LoaderComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

class RequestsPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      activeTab: "waiting",
      search: "",
      viewMode: "card",
      isFilterOpen: false,

      province: "",
      startDate: "",
      endDate: "",

      records: [],
      loading: true,
      authenticated: false,
    };
  }

  componentDidMount() {
    const isAuthenticated = AuthCheck();

    if (!isAuthenticated) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getRequests();
      }
    );
  }

  // =========================================================
  // دریافت درخواست‌ها
  // =========================================================

  getRequests = () => {
    const token = localStorage.getItem("token");

    this.setState({
      loading: true,
    });

    fetch(`${API_URL}/list`, {
      method: "GET",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error(
            "خطا در دریافت درخواست‌ها"
          );
        }

        return response.json();
      })
      .then((data) => {
        console.log("REQUESTS API:", data);

        let requests = [];

        if (Array.isArray(data.requests)) {
          requests = data.requests;
        } else if (Array.isArray(data.data)) {
          requests = data.data;
        } else if (Array.isArray(data.list)) {
          requests = data.list;
        }

        const records = requests.map((request) => {
          const customer =
            request.user ||
            request.customer ||
            request.user_model ||
            request.customer_model ||
            {};

          const technician =
            request.repairman ||
            request.technician ||
            request.repairman_model ||
            request.technician_model ||
            {};

          return {
            id: request.id,

            customerName:
              request.customerName ||
              request.customer_name ||
              request.name ||
              (
                `${customer.name || ""} ${
                  customer.family || ""
                }`
              ).trim() ||
              "---",

            deviceType:
              request.deviceType ||
              request.device_type ||
              request.type ||
              request.device ||
              request.device_name ||
              "---",

            deviceBrand:
              request.deviceBrand ||
              request.device_brand ||
              request.brand ||
              request.brand_name ||
              "---",

            technician:
              request.technician_name ||
              request.repairman_name ||
              (
                `${technician.name || ""} ${
                  technician.family || ""
                }`
              ).trim() ||
              "---",

            problem:
              request.problem ||
              request.device_problem ||
              request.description ||
              request.issue ||
              "---",

            date:
              request.time ||
              request.date ||
              request.created_at ||
              "---",

            status:
              request.status_name ||
              request.status_text ||
              request.state_name ||
              request.status ||
              "waiting",

            province:
              request.state ?? "",

            city:
              request.city ?? "",

            original: request,
          };
        });

        console.log(
          "NORMALIZED RECORDS:",
          records
        );

        this.setState({
          records,
          loading: false,
        });
      })
      .catch((error) => {
        console.error(
          "GET REQUESTS ERROR:",
          error
        );

        this.setState({
          records: [],
          loading: false,
        });
      });
  };

  // =========================================================
  // Search
  // =========================================================

  handleSearchChange = (e) => {
    this.setState({
      search: e.target.value,
    });
  };

  // =========================================================
  // Tabs
  // =========================================================

  handleTabChange = (tab) => {
    this.setState({
      activeTab: tab,
    });
  };

  // =========================================================
  // View Mode
  // =========================================================

  handleViewModeChange = (mode) => {
    this.setState({
      viewMode: mode,
    });
  };

  // =========================================================
  // Open / Close Filter
  // =========================================================

  handleOpenFilter = () => {
    this.setState({
      isFilterOpen: true,
    });
  };

  handleCloseFilter = () => {
    this.setState({
      isFilterOpen: false,
    });
  };

  // =========================================================
  // Province
  // =========================================================

  handleProvinceChange = (e) => {
    this.setState({
      province: e.target.value,
    });
  };

handleStartDateChange = (date) => {
  if (!date) {
    this.setState({
      startDate: null,
    });
    return;
  }

    console.log(
      "START SHAMSI:",
      date.format("YYYY-MM-DD")
    );

    console.log(
      "START GREGORIAN:",
      date
        .convert("gregorian")
        .format("YYYY-MM-DD")
    );

    this.setState({
      startDate: date,
    });
  };

  handleEndDateChange = (date) => {
    if (!date) {
      this.setState({
        endDate: null,
      });
      return;
    }

    console.log(
      "END SHAMSI:",
      date.format("YYYY-MM-DD")
    );

    console.log(
      "END GREGORIAN:",
      date
        .convert("gregorian")
        .format("YYYY-MM-DD")
    );

    this.setState({
      endDate: date,
    });
  };
  // =========================================================
  // Apply Filter
  // =========================================================

  handleApplyFilter = () => {
    const {
      province,
      startDate,
      endDate,
    } = this.state;

    console.log("APPLIED FILTER:", {
      province,
      startDate,
      endDate,
    });

    this.setState({
      isFilterOpen: false,
    });
  };

  // =========================================================
  // تبدیل تاریخ API
  // =========================================================

  normalizeDate = (date) => {
    if (!date) {
      return "";
    }

    let value = String(date).trim();

    if (!value) {
      return "";
    }

    /*
     * مثال:
     * 2026/09/09
     */

    if (
      /^\d{4}\/\d{2}\/\d{2}$/.test(
        value
      )
    ) {
      return value.replace(
        /\//g,
        "-"
      );
    }

    /*
     * مثال:
     * 2026-09-09
     */

    if (
      /^\d{4}-\d{2}-\d{2}$/.test(
        value
      )
    ) {
      return value;
    }

    /*
     * مثال:
     * 2026-09-09T15:00:56.000000Z
     */

    if (value.includes("T")) {
      const datePart =
        value.split("T")[0];

      if (
        /^\d{4}-\d{2}-\d{2}$/.test(
          datePart
        )
      ) {
        return datePart;
      }
    }

    return "";
  };

  // =========================================================
  // Filter Records
  // =========================================================

  getFilteredRequests = () => {
    const {
      records,
      activeTab,
      search,
      province,
      startDate,
      endDate,
    } = this.state;

    const searchText = search
      .trim()
      .toLowerCase();

    return records.filter((record) => {
      // =====================================================
      // وضعیت
      // =====================================================

      let matchesTab = true;

      if (activeTab === "waiting") {
        matchesTab =
          String(record.status) ===
            "waiting" ||
          String(record.status) ===
            "0" ||
          String(record.status) ===
            "pending" ||
          String(record.status) ===
            "pending_confirmation";
      }

      if (activeTab === "confirmed") {
        matchesTab =
          String(record.status) ===
            "confirmed" ||
          String(record.status) ===
            "1";
      }

      if (!matchesTab) {
        return false;
      }

      // =====================================================
      // جستجو
      // =====================================================

      if (searchText) {
        const searchableText = [
          record.customerName,
          record.deviceType,
          record.deviceBrand,
          record.technician,
          record.problem,
        ]
          .map((item) =>
            String(item || "")
              .toLowerCase()
          )
          .join(" ");

        if (
          !searchableText.includes(
            searchText
          )
        ) {
          return false;
        }
      }

      // =====================================================
      // استان
      // =====================================================

      if (province) {
        const requestProvince =
          record.original?.state;

        if (
          String(requestProvince) !==
          String(province)
        ) {
          return false;
        }
      }

      // =====================================================
      // تاریخ درخواست
      // =====================================================

      const requestDate =
        this.normalizeDate(
          record.original?.time ||
            record.original?.date ||
            record.original?.created_at
        );

      /*
       * اگر از تاریخ انتخاب شده باشد
       */

      if (startDate) {
        if (!requestDate) {
          return false;
        }

        if (requestDate < startDate) {
          return false;
        }
      }

      /*
       * اگر تا تاریخ انتخاب شده باشد
       */

      if (endDate) {
        if (!requestDate) {
          return false;
        }

        if (requestDate > endDate) {
          return false;
        }
      }

      return true;
    });
  };

  // =========================================================
  // Render
  // =========================================================

  render() {
    const {
      authenticated,
      loading,
      activeTab,
      search,
      viewMode,
      isFilterOpen,
      province,
      startDate,
      endDate,
    } = this.state;

    if (!authenticated) {
      return <Loader />;
    }

    const filteredRequests =
      this.getFilteredRequests();

    return (
      <div className="container">
        {/* Search */}

        <div
          className="position-relative mb-3"
          style={{
            animation:
              "fadeSlideDown .45s ease",
          }}
        >
          <FaSearch
            className="position-absolute text-secondary"
            style={{
              left: "16px",
              top: "50%",
              transform:
                "translateY(-50%)",
              zIndex: 2,
            }}
          />

          <input
            type="text"
            value={search}
            onChange={
              this.handleSearchChange
            }
            placeholder="جستجو..."
            className="form-control border rounded-pill shadow-none"
            style={{
              height: "58px",
              paddingRight: "20px",
              paddingLeft: "48px",
              fontSize: "15px",
            }}
          />
        </div>

        {/* Tabs */}

        <div
          className="d-flex p-1 mb-4 rounded-pill"
          style={{
            background: "#f5f2ff",
            border:
              "1px solid #eee9ff",
          }}
        >
          <button
            type="button"
            onClick={() =>
              this.handleTabChange(
                "waiting"
              )
            }
            className="btn flex-grow-1 rounded-pill"
            style={{
              height: "52px",
              background:
                activeTab === "waiting"
                  ? "#ffffff"
                  : "transparent",
              color:
                activeTab === "waiting"
                  ? "#5540a8"
                  : "#aaa",
              border:
                activeTab === "waiting"
                  ? "1px solid #7158c9"
                  : "1px solid transparent",
              transition:
                "all .3s cubic-bezier(.22,1,.36,1)",
            }}
          >
            منتظر تایید تعمیرکار
          </button>

          <button
            type="button"
            onClick={() =>
              this.handleTabChange(
                "confirmed"
              )
            }
            className="btn flex-grow-1 rounded-pill"
            style={{
              height: "52px",
              background:
                activeTab ===
                "confirmed"
                  ? "#ffffff"
                  : "transparent",
              color:
                activeTab ===
                "confirmed"
                  ? "#5540a8"
                  : "#aaa",
              border:
                activeTab ===
                "confirmed"
                  ? "1px solid #7158c9"
                  : "1px solid transparent",
              transition:
                "all .3s cubic-bezier(.22,1,.36,1)",
            }}
          >
            تایید شده
          </button>
        </div>

        {/* Toolbar */}

        <div className="d-flex align-items-center justify-content-between mb-2">
          <button
            type="button"
            onClick={
              this.handleOpenFilter
            }
            className="btn bg-white border rounded-4 d-flex align-items-center gap-3 px-4"
            style={{
              height: "58px",
              color: "#777",
            }}
          >
            <span>فیلتر</span>
            <FaFilter size={20} />
          </button>

          <div className="d-flex gap-2">
            <button
              type="button"
              onClick={() =>
                this.handleViewModeChange(
                  "list"
                )
              }
              className="btn bg-white border rounded-4 d-flex align-items-center justify-content-center"
              style={{
                width: "58px",
                height: "58px",
                color:
                  viewMode === "list"
                    ? "#4d3ba3"
                    : "#888",
                boxShadow:
                  viewMode === "list"
                    ? "0 4px 14px rgba(80,60,160,.08)"
                    : "none",
              }}
            >
              <FaBars size={23} />
            </button>

            <button
              type="button"
              onClick={() =>
                this.handleViewModeChange(
                  "card"
                )
              }
              className="btn bg-white border rounded-4 d-flex align-items-center justify-content-center"
              style={{
                width: "58px",
                height: "58px",
                color:
                  viewMode === "card"
                    ? "#4d3ba3"
                    : "#888",
                boxShadow:
                  viewMode === "card"
                    ? "0 4px 14px rgba(80,60,160,.08)"
                    : "none",
              }}
            >
              <FaTh size={23} />
            </button>
          </div>
        </div>

        {/* Records */}

        {loading ? (
          <div className="py-5">
            <Loader />
          </div>
        ) : (
          <RequestRecords
            records={filteredRequests}
            viewMode={viewMode}
          />
        )}

        {/* Filter */}

        <FilterModal
          isOpen={isFilterOpen}
          onClose={
            this.handleCloseFilter
          }
          onApply={
            this.handleApplyFilter
          }
          province={province}
          startDate={startDate}
          endDate={endDate}
          onProvinceChange={
            this.handleProvinceChange
          }
          onStartDateChange={
            this.handleStartDateChange
          }
          onEndDateChange={
            this.handleEndDateChange
          }
        />

        <style>
          {`
            @keyframes fadeSlideDown {
              from {
                opacity: 0;
                transform: translateY(-10px);
              }

              to {
                opacity: 1;
                transform: translateY(0);
              }
            }
          `}
        </style>
      </div>
    );
  }
}

export default RequestsPage;
